import React, { useState } from 'react';
import './TherapyChat.css';

const TherapyChat = () => {
  const [messages, setMessages] = useState([
    { role: 'assistant', content: "Hello! I'm your mindfulness therapy assistant. How are you feeling today?" }
  ]);
  const [newMessage, setNewMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSendMessage = (e) => {
    e.preventDefault();
    
    if (!newMessage.trim()) return;
    
    // Add user message
    const updatedMessages = [
      ...messages,
      { role: 'user', content: newMessage }
    ];
    
    setMessages(updatedMessages);
    setNewMessage('');
    setIsLoading(true);
    
    // Simulate AI response
    setTimeout(() => {
      setMessages([
        ...updatedMessages,
        { 
          role: 'assistant', 
          content: "This is a placeholder response. The actual therapy agent will be connected to the backend API for real responses. Try asking something else!" 
        }
      ]);
      setIsLoading(false);
    }, 1000);
  };

  return (
    <div className="therapy-chat-page">
      <div className="container">
        <div className="chat-container">
          <div className="chat-header">
            <h1>Therapy Chat</h1>
          </div>
          
          <div className="chat-messages">
            {messages.map((message, index) => (
              <div key={index} className={`message message-${message.role}`}>
                {message.content}
              </div>
            ))}
            
            {isLoading && (
              <div className="message message-assistant loading">
                <div className="loading-dots">
                  <span></span>
                  <span></span>
                  <span></span>
                </div>
              </div>
            )}
          </div>
          
          <form className="chat-input-form" onSubmit={handleSendMessage}>
            <input
              type="text"
              placeholder="Type your message..."
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              disabled={isLoading}
            />
            <button 
              type="submit" 
              className="btn btn-primary"
              disabled={isLoading || !newMessage.trim()}
            >
              Send
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default TherapyChat;
